func TestEveryPickleFormIsRefusedUnderAnotherName(t *testing.T) {
	decoy := map[string]bool{"openvino_model.xml": true}
	for name, data := range realPickles {
		for _, file := range []string{"model.onnx", "openvino_model.bin", "weights.npy"} {
			p := filepath.Join(t.TempDir(), file)
			os.WriteFile(p, data, 0o644)
			if err := checkFormat(p, file, isPickle(file, decoy)); err == nil {
				t.Errorf("%s as %s: passed the format check", name, file)
			}
		}
	}
}

func TestOpcodeWalkHasNoFalsePositives(t *testing.T) {
	random := make([]byte, 64<<10)
	rand.Read(random)
	onnxLike := append([]byte{0x08, 0x07, 0x12, 0x07, 'p', 'y', 't', 'o', 'r', 'c', 'h'}, random[:4096]...)
	cases := map[string][]byte{
		"random.onnx":       random,
		"model.onnx":        onnxLike,
		"vocab.txt":         []byte("cat\ndog\n(\n."),
		"starts_with_n.bin": append([]byte("N"), random[:100]...),
	}
	for name, data := range cases {
		p := filepath.Join(t.TempDir(), name)
		os.WriteFile(p, data, 0o644)
		if err := checkFormat(p, name, false); err != nil {
			t.Errorf("%s: refused: %v", name, err)
		}
	}
}
